      chapterId: "sci_ch_03_metals_non_metals",
      questionText: "[QUESTIONS (Page 49)] Why do ionic compounds have remarkably high melting points?",
      options: const [
        QuestionOption(id: "A", text: "A tremendous amount of thermal energy is required to overcome the strong electrostatic inter-ionic attractions holding the crystal lattice together.", isCorrect: true),
