    Question(
      id: "sci_ch3_p53_q02",
      subject: Subject.science,
      chapterId: "sci_ch_03_metals_non_metals",
      questionText: "[QUESTIONS (Page 53)] Which pair of metals are found in nature predominantly in the native (free uncombined) state?",
      options: const [
