    Question(
      id: "sci_ch3_ex_q03",
      subject: Subject.science,
      chapterId: "sci_ch_03_metals_non_metals",
      questionText: "[NCERT Exercise 3] An element reacts with oxygen to give a compound with a high melting point. This compound is also soluble in water. The element is likely to be:",
      options: const [
