      questionText: "[NCERT Exercise 7] Name two metals which will displace hydrogen from dilute acids, and two metals which will not.",
      options: const [
        QuestionOption(id: "A", text: "Displace hydrogen: Zinc (\$\\text{Zn}\$) and Iron (\$\\text{Fe}\$); Will not displace: Copper (\$\\text{Cu}\$) and Silver (\$\\text{Ag}\$)", isCorrect: true),
        QuestionOption(id: "B", text: "Displace hydrogen: Copper (\$\\text{Cu}\$) and Gold (\$\\text{Au}\$); Will not displace: Magnesium (\$\\text{Mg}\$) and Calcium (\$\\text{Ca}\$)", isCorrect: false),
        QuestionOption(id: "C", text: "Displace hydrogen: Silver (\$\\text{Ag}\$) and Platinum (\$\\text{Pt}\$); Will not displace: Sodium (\$\\text{Na}\$) and Potassium (\$\\text{K}\$)", isCorrect: false),
        QuestionOption(id: "D", text: "All metals displace hydrogen from dilute acids without exception.", isCorrect: false),
