    ),
    Question(
      id: "sci_ch3_ex_q12_c",
      subject: Subject.science,
      chapterId: "sci_ch_03_metals_non_metals",
      questionText: "[NCERT Exercise 12(c)] Aluminium is a highly reactive metal, yet it is extensively used to manufacture cooking utensils. What is the reason?",
      options: const [
        QuestionOption(id: "A", text: "It rapidly forms a thin, tough, non-porous protective surface layer of Aluminium oxide (\$\\text{Al}_2\\text{O}_3\$) that prevents further corrosion, combined with high thermal conductivity and light weight.", isCorrect: true),
        QuestionOption(id: "B", text: "Aluminium becomes completely unreactive when heated above 50°C.", isCorrect: false),
        QuestionOption(id: "C", text: "It is cheaper than clay and dissolves completely in water after cooking.", isCorrect: false),
        QuestionOption(id: "D", text: "It absorbs food toxins and converts all organic acids into neutral sugars.", isCorrect: false),
      ],
      stepByStepSolution: "Correct Answer: (A) It rapidly forms a thin, tough, non-porous protective surface layer of Aluminium oxide (\$\\text{Al}_2\\text{O}_3\$) that prevents further corrosion, combined with high thermal conductivity and light weight.\n\nScientific Principle / Key Concept:\nThough aluminium is a reactive metal, on exposure to air it quickly develops a thin, adherent, non-porous protective oxide film:\n\$\$4\\text{Al} + 3\\text{O}_2 \\rightarrow 2\\text{Al}_2\\text{O}_3\$\$\nThis oxide layer passivates the metal and protects the underlying aluminium from corrosion and attack by moisture or food ingredients. Coupled with its excellent thermal conductivity, light weight, and high malleability, it is ideal for cooking utensils.\n\nDetailed Distractor & Misconception Analysis:\n• Option (B): Incorrect. Passivation is due to the oxide layer, not heat neutralization.\n• Option (C): Incorrect. Aluminium is insoluble.\n• Option (D): Incorrect. Utensils do not convert food acids into sugars.",
      difficultyLevel: DifficultyLevel.medium,
      status: QuestionStatus.approved,
      submittedBy: '00000000-0000-0000-0000-000000000001',
      reviewedBy: '00000000-0000-0000-0000-000000000001',
      createdAt: DateTime.fromMillisecondsSinceEpoch(1727200000000 + 44000),
    ),
    Question(
